package com.example.agendapersonal.ui;
import android.content.Context;import android.util.AttributeSet;import android.view.View;import android.graphics.*;
public class RadarView extends View {
 private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private final float[]azul=new float[6],rojo=new float[6];private final String[]etiquetas={"Estudios","Sociales","Salud","Trabajo","Ejercicio","Freelance"};
 public RadarView(Context c,AttributeSet a){super(c,a);}
 public void datos(float[]porcentajes,int[]finalizadas,int escala){StringBuilder accesible=new StringBuilder("Radar de progreso. ");for(int i=0;i<6;i++){azul[i]=Math.max(0,Math.min(1,porcentajes[i]));rojo[i]=Math.max(0,Math.min(1,finalizadas[i]/(float)Math.max(1,escala)));accesible.append(etiquetas[i]).append(": ").append(Math.round(azul[i]*100)).append(" por ciento de tareas no pendientes y ").append(finalizadas[i]).append(" actividades finalizadas. ");}setContentDescription(accesible);invalidate();}
 @Override protected void onDraw(Canvas c){super.onDraw(c);float d=getResources().getDisplayMetrics().density;float x=getWidth()/2f,y=getHeight()/2f,r=Math.min(getWidth()/2f-66*d,getHeight()/2f-30*d);p.setStrokeWidth(d);p.setStyle(Paint.Style.STROKE);p.setColor(Tema.color(getContext(),com.example.agendapersonal.R.attr.agenda_border));for(int nivel=1;nivel<=5;nivel++){Path path=new Path();for(int i=0;i<6;i++){double a=Math.PI*2*i/6-Math.PI/2;float px=x+(float)Math.cos(a)*r*nivel/5,py=y+(float)Math.sin(a)*r*nivel/5;if(i==0)path.moveTo(px,py);else path.lineTo(px,py);}path.close();c.drawPath(path,p);}for(int i=0;i<6;i++){double a=Math.PI*2*i/6-Math.PI/2;c.drawLine(x,y,x+(float)Math.cos(a)*r,y+(float)Math.sin(a)*r,p);}dibujar(c,x,y,r,azul,0xff4177cb);dibujar(c,x,y,r,rojo,0xffcc5153);p.setStyle(Paint.Style.FILL);p.setColor(Tema.color(getContext(),com.example.agendapersonal.R.attr.agenda_text_secondary));p.setTextSize(11*getResources().getDisplayMetrics().scaledDensity);for(int i=0;i<6;i++){double a=Math.PI*2*i/6-Math.PI/2;float px=x+(float)Math.cos(a)*(r+16*d),py=y+(float)Math.sin(a)*(r+16*d);p.setTextAlign(i==0||i==3?Paint.Align.CENTER:i<3?Paint.Align.LEFT:Paint.Align.RIGHT);c.drawText(etiquetas[i],px,py+4*d,p);}}
 private void dibujar(Canvas c,float x,float y,float r,float[]valores,int color){Path path=new Path();for(int i=0;i<6;i++){double a=Math.PI*2*i/6-Math.PI/2;float px=x+(float)Math.cos(a)*r*valores[i],py=y+(float)Math.sin(a)*r*valores[i];if(i==0)path.moveTo(px,py);else path.lineTo(px,py);}path.close();p.setStyle(Paint.Style.FILL);p.setColor((color&0x00ffffff)|0x22000000);c.drawPath(path,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2*getResources().getDisplayMetrics().density);p.setColor(color);c.drawPath(path,p);}
}
